cat > src/tasks.js <<'EOF'
function createStore() { return { tasks: [] }; }
function add(store, title) {
  const task = { id: store.tasks.length + 1, title, done: false };
  store.tasks.push(task);
  return task;
}
function list(store) { return store.tasks.slice(); }
module.exports = { createStore, add, list };
EOF
cat > tests/tasks.test.js <<'EOF'
const { test } = require('node:test');
const assert = require('node:assert');
const { createStore, add, list } = require('../src/tasks');
test('add returns the task and list shows it', () => {
  const s = createStore();
  const t = add(s, 'buy milk');
  assert.equal(t.title, 'buy milk');
  assert.equal(list(s).length, 1);
});
EOF
cat > README.md <<'EOF'
# tasklist

A tiny task list library with an in-memory store.

## Usage

```js
const { createStore, add, list } = require('./src/tasks');
const store = createStore();
add(store, 'buy milk');
console.log(list(store));
```
EOF

# Auth and a users table already exist, so "email verification on signup"
# touches an auth boundary AND the data model - two of the five SENSITIVE
# categories. The spec must carry the marker.
cat > src/users.js <<'EOS'
// In-memory users table. Columns: id, email, passwordHash, createdAt.
const users = [];
function signup(email, passwordHash) {
  if (users.some(u => u.email === email)) throw new Error('email taken');
  const u = { id: users.length + 1, email, passwordHash, createdAt: Date.now() };
  users.push(u);
  return u;
}
function login(email, passwordHash) {
  const u = users.find(x => x.email === email && x.passwordHash === passwordHash);
  if (!u) throw new Error('invalid credentials');
  return { token: 'tok-' + u.id };
}
module.exports = { signup, login, users };
EOS
